extern "C" void ref_model_eval(unsigned long long* nmi_evt_ref,unsigned long long* per_dout_ref,unsigned long long* wdtifg_set_ref,unsigned long long* wdtpw_error_ref,unsigned long long* wdttmsel_ref,unsigned long long aclk_en,unsigned long long dbg_freeze,unsigned long long mclk,unsigned long long nmi,unsigned long long nmie,unsigned long long per_addr,unsigned long long per_din,unsigned long long per_en,unsigned long long per_wen,unsigned long long puc,unsigned long long smclk_en){static VerilatedContext context;static RefModel model(&context);model.aclk_en=aclk_en;model.dbg_freeze=dbg_freeze;model.mclk=mclk;model.nmi=nmi;model.nmie=nmie;model.per_addr=per_addr;model.per_din=per_din;model.per_en=per_en;model.per_wen=per_wen;model.puc=puc;model.smclk_en=smclk_en;model.eval();*nmi_evt_ref=model.nmi_evt_ref;*per_dout_ref=model.per_dout_ref;*wdtifg_set_ref=model.wdtifg_set_ref;*wdtpw_error_ref=model.wdtpw_error_ref;*wdttmsel_ref=model.wdttmsel_ref;}
